  '日付の計算（要望1-③）を追加しました。基準日（現在日時／対象ファイル更新日／対象ファイル作成日）を軸に、年・月・週・日・時・分・秒を前後へずらせます。ExcelのEDATE関数やVBAのDateAddのように「Nヶ月前」「N年後」などをタグへ組み込めます（例: 前月度、前年、過去7日基準）。月末を跨ぐ計算はEDATE同様に月末へ丸めます。',
